@_register("dow_structure", "داو والتحليل الكلاسيكي", ["confirmed pivots"], "structure", 40)
def dow_structure(b, c):
    p = c["pivots"]
    highs = [x for x in p if x["kind"] == "HIGH"]
    lows = [x for x in p if x["kind"] == "LOW"]
    if len(highs) < 2 or len(lows) < 2:
        return _result(missing=["two confirmed highs and lows"])
    up = highs[-1]["price"] > highs[-2]["price"] and lows[-1]["price"] > lows[-2]["price"]
    down = highs[-1]["price"] < highs[-2]["price"] and lows[-1]["price"] < lows[-2]["price"]
    side = "BUY" if up else "SELL" if down else "NEUTRAL"
    level = highs[-1]["price"] if up else lows[-1]["price"] if down else None
    triggered = (up and b[-2]["close"] <= level < b[-1]["close"]) or (down and b[-2]["close"] >= level > b[-1]["close"])
    return _result(side, triggered, level, lows[-1]["price"] if up else highs[-1]["price"] if down else None,
                   evidence=highs[-2:]+lows[-2:], met=["confirmed structure"] if side != "NEUTRAL" else [],
                   missing=[] if triggered else ["fresh close through confirmed swing"])

@_register("classic_reversal_patterns", "الأنماط الانعكاسية الكلاسيكية",
           ["confirmed pivots", "double top/bottom", "head and shoulders", "neckline close"],
           "structure", 60)
def classic_reversal_patterns(b, c):
    swings = _alternating_pivots(c["pivots"])
    pattern = _head_shoulders(swings, c["atr"], len(b)-2, len(b)-1)
    if pattern is None:
        pattern = _double_reversal(swings, c["atr"])
    if pattern is None:
        return _result(
            evidence=[_evidence("reversal_pattern_scan", {"confirmed_swings": swings[-5:]}, b,
                                "classical reversal geometry")],
            missing=["confirmed classical reversal geometry"],
            assumptions=["Pattern names describe explicit OHLC geometry, not a forecast guarantee"],
        )
    side = pattern["side"]
    previous_close, current_close = b[-2]["close"], b[-1]["close"]
    triggered = (previous_close <= pattern["neckline_previous"] and current_close > pattern["neckline_now"]
                 if side == "BUY" else
                 previous_close >= pattern["neckline_previous"] and current_close < pattern["neckline_now"])
    details = {key: value for key, value in pattern.items() if key not in ("pivots", "geometry_rule")}
    details["last_pivot_confirmed_at"] = max(p["confirmed_at"] for p in pattern["pivots"])
    return _result(
        side, triggered, pattern["neckline_now"], pattern["invalidation"],
        [_evidence("reversal_pattern", details, b, "classical reversal geometry"), *pattern["pivots"]],
        [pattern["geometry_rule"]] + (["fresh completed close through the neckline"] if triggered else []),
        [] if triggered else ["neckline break on the latest completed bar"],
        ["Pattern names describe explicit OHLC geometry, not a forecast guarantee"],
        targets=[{"price": pattern["target"], "method": "pattern height projected from neckline", "fraction": 1.0}]
        if triggered else None,
    )

@_register("fib_retracement", "فيبوناتشي", ["confirmed swing", "0.618 retracement"], "structure", 60)
def fib_retracement(b, c):
    p = _alternating_pivots(c["pivots"])
    pair = None
    for a, z in itertools.pairwise(p):
        if a["kind"] != z["kind"] and z["confirmed_at"] <= b[-1]["time"]:
            pair = a, z
    if not pair:
        return _result(missing=["confirmed alternating swing pair"])
    a, z = pair
    bull_swing = a["kind"] == "LOW" and z["kind"] == "HIGH"
    span = abs(z["price"]-a["price"])
    level = z["price"]-.618*span if bull_swing else z["price"]+.618*span
    recovery = z["price"]-.5*span if bull_swing else z["price"]+.5*span
    touched = b[-1]["low"] <= level+.1*c["atr"] if bull_swing else b[-1]["high"] >= level-.1*c["atr"]
    valid = span > 2*c["atr"] and touched and (b[-2]["close"] <= recovery < b[-1]["close"] if bull_swing else b[-2]["close"] >= recovery > b[-1]["close"])
    return _result("BUY" if bull_swing else "SELL", valid, recovery, a["price"],
                   [a, z, _evidence("horizontal_level", level, b, "0.618 pullback"), _evidence("horizontal_level", recovery, b, "0.5 recovery trigger")],
                   ["confirmed swing"] + (["pullback recovery"] if valid else []), [] if valid else ["0.618 touch and fresh 0.5 recovery"])

@_register("ema_cross", "اتباع الاتجاه", ["EMA 12", "EMA 26", "ATR 14"], "trend", 60)
def ema_cross(b, c):
    closes = [x["close"] for x in b]
    fast, slow = ema(closes, 12), ema(closes, 26)
    bull = fast[-2] <= slow[-2] and fast[-1] > slow[-1]
    bear = fast[-2] >= slow[-2] and fast[-1] < slow[-1]
    return _result("BUY" if fast[-1] > slow[-1] else "SELL" if fast[-1] < slow[-1] else "NEUTRAL", bull or bear, closes[-1],
                   min(x["low"] for x in b[-5:]) if fast[-1] > slow[-1] else max(x["high"] for x in b[-5:]),
                   [_evidence("line", fast[-1], b, "EMA12"), _evidence("line", slow[-1], b, "EMA26")],
                   (["EMA directional ordering"] if fast[-1] != slow[-1] else []) + (["fresh EMA crossover"] if bull or bear else []), [] if bull or bear else ["fresh EMA crossover"])

@_register("rsi_rebound", "مؤشرات الزخم", ["simple RSI 14"], "momentum", 30)
def rsi_rebound(b, c):
    closes = [x["close"] for x in b]
    before, now = rsi(closes[:-1]), rsi(closes)
    bull, bear = before <= 30 < now, before >= 70 > now
    return _result("BUY" if bull else "SELL" if bear else "NEUTRAL", bull or bear, closes[-1],
                   min(x["low"] for x in b[-5:]) if bull else max(x["high"] for x in b[-5:]),
                   [_evidence("oscillator", {"previous": before, "current": now}, b, "simple RSI14")],
                   ["fresh threshold recovery"] if bull or bear else [], [] if bull or bear else ["RSI recross 30 or 70"],
                   ["Simple rolling gain/loss RSI; deliberately not Wilder smoothing"])

@_register("vwap_reclaim", "VWAP وAnchored VWAP", ["typical-price weighted mean", "explicit anchor"], "volume", 30,
           requirements=["completed_ohlc", "bar_real_volume_or_labeled_tick_proxy", "explicit_anchor"])
def vwap_reclaim(b, c):
    anchor = c.get("anchor_time", (b[-1]["time"]//86400)*86400)
    if b[0]["time"] > anchor:
        return _result(status="DATA_MISSING", missing=["history does not cover the declared anchor boundary"])
    anchored = [x for x in b if x["time"] >= anchor]
    if len(anchored) < 3:
        return _result(status="DATA_MISSING", missing=["at least three completed bars after anchor"])
    real = all(x["real_volume"] > 0 for x in anchored)
    key = "real_volume" if real else "tick_volume"
    if any(x[key] <= 0 for x in anchored):
        return _result(status="DATA_MISSING", missing=["positive weights for each anchored bar"])
    def weighted(items):
        return sum(((x["high"]+x["low"]+x["close"])/3)*x[key] for x in items)/sum(x[key] for x in items)
    previous, current = weighted(anchored[:-1]), weighted(anchored)
    bull = b[-2]["close"] <= previous and b[-1]["close"] > current and b[-1]["close"] > b[-1]["open"]
    bear = b[-2]["close"] >= previous and b[-1]["close"] < current and b[-1]["close"] < b[-1]["open"]
    return _result("BUY" if bull else "SELL" if bear else "NEUTRAL", bull or bear, current, current,
                   [_evidence("weighted_mean", current, b, "bar VWAP" if real else "tick-weighted typical-price proxy", anchor_time=anchor, weight_source=key)],
                   ["fresh weighted-mean reclaim"] if bull or bear else [], [] if bull or bear else ["fresh reclaim"],
                   ["Bar typical-price approximation, not trade-level VWAP", "Real volume is venue/broker supplied, not asserted centralized"] if real else
                   ["Tick volume is activity count, not centralized traded volume", "Tick-weighted mean is a proxy, not genuine transaction VWAP"])

def interasset(b,c):
    pairs=aligned(b,c)
    if pairs is None:return wait(b,"aligned declared MT5 partner required",missing=True)
    # The old complete arithmetic is retained; its previous missing wiring is
    # now supplied by Engine's declared metadata mapping.
    return st.interasset_confirmation(b,{**c,"partner_bars":[p[1] for p in pairs]})

def liquidity_gap(b,c):
    result=first_return(b,"gap")
    if not result["triggered"]:return result
    details=result["evidence"][0]["value"]
    end=next(i for i,x in enumerate(b) if x["time"]==details["formation_time"])
    sweep=b[end-2];prior=b[end-12:end-2]
    if len(prior)!=10:return wait(b)
    lo=min(x["low"] for x in prior);hi=max(x["high"] for x in prior)
    valid=(sweep["low"]<lo<sweep["close"] if result["direction"]=="BUY" else sweep["high"]>hi>sweep["close"])
    if not valid:return wait(b,"prior sweep required for local liquidity model",details)
    result["assumptions"].append("Local sweep plus gap return; no institutional orders or full ICT interpretation")
    return result

def supply_zone(b,c):
    result=first_return(b,"base")
    if not result["triggered"]:return result
    mean=st.ema([x["close"] for x in b[:-1]],20)[-1]
    if (result["direction"]=="BUY" and b[-1]["close"]<=mean) or (result["direction"]=="SELL" and b[-1]["close"]>=mean):
        return wait(b)
    result["assumptions"].append("First-return OHLC zone with prior EMA filter; not observed supply or demand orders")
    return result

def monthly_bias(b,c):
    info=c.get("symbol_info",{});base=info.get("currency_base","");quote=info.get("currency_profit","")
    currencies={"USD","EUR","GBP","JPY","CHF","CAD","AUD","NZD","ZAR","MXN","HKD","SGD","NOK","SEK","PLN","TRY","CNH"}
    if base not in currencies or quote not in currencies or base==quote:
        return wait(b,"local monthly model supports declared currency pairs only",missing=True)
    daily=c.get("daily_bars",[])
    try:daily=st.validate_bars([x for x in daily if x["time"]+86400<=c["as_of"]],"D1",c["as_of"])
    except (st.DataError,KeyError,TypeError):return wait(b,"completed multi-year MT5 daily history required",missing=True)
    now=datetime.fromtimestamp(c["as_of"],UTC)
    groups={}
    for x in daily:
        d=datetime.fromtimestamp(x["time"],UTC)
        if d.month==now.month and d.year<now.year:groups.setdefault(d.year,[]).append(x)
    returns=[]
    for group in groups.values():
        first=datetime.fromtimestamp(group[0]["time"],UTC);last=datetime.fromtimestamp(group[-1]["time"],UTC)
        if len(group)>=15 and first.day<=7 and last.day>=24:
            value=group[-1]["close"]/group[0]["open"]-1
            if abs(value)>.5:return wait(b,"historical discontinuity in local monthly sample",missing=True)
            returns.append(value)
    if len(returns)<3:return wait(b,"three complete earlier same-month samples required",missing=True)
    mean=statistics.fmean(returns);sd=statistics.stdev(returns)
    score=mean/(sd/math.sqrt(len(returns))) if sd>0 else 0.
    agreement=sum(x*mean>0 for x in returns)/len(returns)
    hi=max(x["high"] for x in b[-21:-1]);lo=min(x["low"] for x in b[-21:-1])
    result=signal(b,score>=2 and agreement>=2/3 and b[-2]["close"]<=hi<b[-1]["close"],
                  score<=-2 and agreement>=2/3 and b[-2]["close"]>=lo>b[-1]["close"],lo,hi,
                  {"sample_count": len(returns),"mean": mean,"score": score,"agreement": agreement,"month": now.month})
    result["assumptions"].append("Raw broker FX monthly sample; no adjusted futures history, stationarity or seasonal profitability claim")
    return result

@specialist("classic_pivot_reclaim", "استعادة النقطة المحورية اليومية", "Previous-session classic pivot reclaim", "structure",
            ["P=(H+L+C)/3, R1=2P-L, S1=2P-H, R2=P+(H-L), S2=P-(H-L), from a completed MT5 D1 bar only",
             "Intraday trigger pair shares the declared daily clock; reference closes before both trigger bars and is at most four days old",
             "Fresh directional close through P, inside first resistance/support; structural stop and first level target"],
            {"reference_timeframe": "D1", "max_reference_age_seconds": 345600,
             "entry_definition": "fresh pivot reclaim; no entry merely because price touches a level"})
def classic_pivot_reclaim(b, c):
    from .strategies import PERIODS, DataError, bar_close_time, validate_bars
    if c.get("timeframe") not in PERIODS or PERIODS[c["timeframe"]] >= 86400:
        return _result(missing=["daily pivot reclaim is an intraday model"])
    daily = c.get("daily_bars")
    if not daily:
        return _result(status="DATA_MISSING", missing=["completed MT5 daily reference required for classic pivots"])
    # Walk-forward context may include later history. It never enters this
    # reference; a new daily level must have existed before BOTH trigger bars.
    try:
        eligible = [x for x in daily if bar_close_time(x["time"], "D1") <= b[-2]["time"]]
        refs = validate_bars(eligible, "D1", c["as_of"])
    except (DataError, KeyError, TypeError, ValueError, OverflowError):
        return _result(status="DATA_MISSING", missing=["completed MT5 daily reference required for classic pivots"])
    if not refs:
        return _result(status="DATA_MISSING", missing=["completed MT5 daily reference required for classic pivots"])
    ref, previous, last = refs[-1], b[-2], b[-1]
    close_time = bar_close_time(ref["time"], "D1")
    same_clock_day = int((previous["time"]-ref["time"])/86400) == int((last["time"]-ref["time"])/86400)
    if not same_clock_day or last["time"]-close_time > 345600 or ref["high"] <= ref["low"]:
        return _result(missing=["daily pivot reference or trigger session is outside declared scope"])
    pivot = ref["high"]/3+ref["low"]/3+ref["close"]/3
    r1, s1 = 2*pivot-ref["low"], 2*pivot-ref["high"]
    r2, s2 = pivot+ref["high"]-ref["low"], pivot-ref["high"]+ref["low"]
    if any(not math.isfinite(p) or p <= 0 for p in (pivot, r1, s1, r2, s2)):
        return _result(missing=["classic pivot levels must be finite and positive"])
    bull = previous["close"] <= pivot < last["close"] < r1 and last["close"] > last["open"]
    bear = previous["close"] >= pivot > last["close"] > s1 and last["close"] < last["open"]
    result = signal(b, bull, bear, min(last["low"], s1), max(last["high"], r1),
                    {"pivot": pivot, "resistance_1": r1, "support_1": s1,
                         "resistance_2": r2, "support_2": s2,
                         "reference_open": ref["time"], "reference_close": close_time,
                         "daily_clock": "MT5 D1 opening clock; no exchange-session claim"},
                    r1 if bull else s1 if bear else None)
    result["assumptions"].append("Classic pivot formula; reclaim, four-day expiry and exits are house definitions")
    if result["targets"]:
        result["targets"][0]["method"] = "first classic pivot resistance or support"
    return result

